-- Group D, story text (Fake Guru, 17 Oct: "merged. you decide the rest"; gameplay verdict §4 D), data only:
-- * The seven flavour choices (W1D4 ×3, W1D6, W2D1, W2D6, W3D6) give each option a passage of its own (mode 'pick').
-- * Every weekday fight has a line of its own for a loss (W1D3, W1D5, W2D5, W3D1, W3D5, W4D2, W4D5, W5D2, W6D4, W6D6).
-- * Gathering 1's drop scene: the friend in the drop works from below (they now take turns, 0085).
-- * Gatherings 2 to 4: the Ask tables' stage notes ("Asked how:", "Asked why: silence.", "Pressed on…:", "Silence.")
--   become narration; every spoken line is unchanged.
-- Small patches against the rows as they were (scripts/gen-chapters-sql.ts and gen-gathering-sql.ts give the full rows);
-- every changed row md5-checked against the local copy's full regeneration. Applied live in parts; Gatherings 2 to 4
-- went in through execute_sql in an equivalent form, as apply_migration stalled on them.
update public.chapters set script = jsonb_insert(script, '{steps,7}', $p${"t":"say","text":"You are still sitting in the crushed bracken when {F3} gets back, with the wind knocked clean out of you and a bruise coming up along your ribs that you will feel for days.","cond":{"on":"fight","won":false}}$p$::jsonb) where series_id = 'dark-moon' and season_number = 1 and week = 1 and day = 3;
update public.chapters set script = jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(script, '{steps,3,mode}', $p$"pick"$p$::jsonb), '{steps,3,branches}', $p$[{"options":[0],"text":"You crouch by the bucket. The mud there has been trodden by every boot in Fenmark, but over the top of it all runs a line of small prints, quick and light, too short in the stride for any grown man. They go off between the sheds behind the lane, and there you lose them."},{"options":[1],"text":"The door beside the well opens the width of a hand before your knuckles have finished on it. An eye, a grey braid, a thin hand on the latch. She does not speak, and she does not shut it. Her gaze goes once, quickly, down the lane and back to you."}]$p$::jsonb), '{steps,8,mode}', $p$"pick"$p$::jsonb), '{steps,8,branches}', $p$[{"options":[0],"text":"You unfold Meira's list and hold it where he can see. He reads it slowly, his lips moving, then looks up from the names to your faces, one after another, as if to make sure you are the people written there. Something in his shoulders lets go."},{"options":[1],"text":"You ask him straight out who they took. His chin comes up at that. For three days Fenmark has told him only to keep quiet, and nobody has asked him anything at all."},{"options":[2],"text":"You say nothing. You lean on the cold lip of the well and let the quiet be, as if you had the whole afternoon to spend on it. The boy watches you do it. He had braced himself for questions."}]$p$::jsonb), '{steps,16,mode}', $p$"pick"$p$::jsonb), '{steps,16,branches}', $p$[{"options":[0],"text":"You stay exactly where you are, your feet set on the wet cobbles. The two younger men had expected you to give ground. They glance at the elder, and do not quite know what to do with their hands."},{"options":[1],"text":"You take one slow step back and let them see your empty hands. The nearer of the two young men lets out a breath, and some of the stiffness goes out of the street."},{"options":[2],"text":"You step across, between the men and the boy. It is a small movement, and every eye in the lane follows it. The elder's face changes. For a moment he looks less like a man guarding his village than a man ashamed of it."}]$p$::jsonb) where series_id = 'dark-moon' and season_number = 1 and week = 1 and day = 4;
update public.chapters set script = jsonb_insert(script, '{steps,7}', $p${"t":"say","text":"Your shoulder is against the shed wall where he threw you, and the boards are rough and cold through your shirt. It is a while before your hands stop shaking.","cond":{"on":"fight","won":false}}$p$::jsonb) where series_id = 'dark-moon' and season_number = 1 and week = 1 and day = 5;
update public.chapters set script = jsonb_set(jsonb_set(script, '{steps,19,mode}', $p$"pick"$p$::jsonb), '{steps,19,branches}', $p$[{"options":[0],"text":"You smooth the map flat between the cups and read it yourself, tracing each line with a fingertip so the others can follow it, from the ford all the way to the mark."},{"options":[1],"text":"You turn the map round and slide it across to {F2}, who reads it the way some people read a letter from home: slowly, frowning a little, as if the words might change if they were hurried."}]$p$::jsonb) where series_id = 'dark-moon' and season_number = 1 and week = 1 and day = 6;
update public.chapters set script = jsonb_set(jsonb_set(script, '{steps,4,mode}', $p$"pick"$p$::jsonb), '{steps,4,branches}', $p$[{"options":[0],"text":"You crouch down in the road until your eyes are level with hers, and the mud soaks cold through your knee. She studies your face for a long moment, very seriously, the way children study a stranger's dog."},{"options":[1],"text":"You ask her what the song is. She stops humming at once, as if she had been caught at something. *\"It's a counting one,\"* she tells you, as though anybody ought to know that."},{"options":[2],"text":"You say nothing. You only wait with her in the road, while the carter shifts on his seat and the horse blows. After a while her good hand finds your sleeve, and holds on to a fold of it."}]$p$::jsonb) where series_id = 'dark-moon' and season_number = 1 and week = 2 and day = 1;
update public.chapters set script = jsonb_insert(script, '{steps,10}', $p${"t":"say","text":"He gave as good as he got, and better. Your lip is split, you can taste iron, and the strip of coat is the only thing you took from him.","cond":{"on":"fight","won":false}}$p$::jsonb) where series_id = 'dark-moon' and season_number = 1 and week = 2 and day = 5;
update public.chapters set script = jsonb_set(jsonb_set(script, '{steps,13,mode}', $p$"pick"$p$::jsonb), '{steps,13,branches}', $p$[{"options":[0],"text":"You keep your voice low and even, and give it line by line, the way you would give the road to a stranger at a crossroads."},{"options":[1],"text":"You pass it to {F3}, who tilts it to the starlight and reads it slowly, stopping at every turn of the way to be sure of it."}]$p$::jsonb) where series_id = 'dark-moon' and season_number = 1 and week = 2 and day = 6;
update public.chapters set script = jsonb_insert(script, '{steps,10}', $p${"t":"say","text":"You are left sitting in that wet grass, one sleeve torn from cuff to elbow, waiting for the hillside to stop tilting.","cond":{"on":"fight","won":false}}$p$::jsonb) where series_id = 'dark-moon' and season_number = 1 and week = 3 and day = 1;
update public.chapters set script = jsonb_insert(script, '{steps,6}', $p${"t":"say","text":"He never once hurried, and he never once let you close. Your knuckles are skinned raw on the black rock, and he did not lose so much as his hat.","cond":{"on":"fight","won":false}}$p$::jsonb) where series_id = 'dark-moon' and season_number = 1 and week = 3 and day = 5;
update public.chapters set script = jsonb_set(jsonb_set(script, '{steps,16,mode}', $p$"pick"$p$::jsonb), '{steps,16,branches}', $p$[{"options":[0],"text":"You have to raise your voice over the wind, and you give it one turn at a time: the crack, the cut way, the room below."},{"options":[1],"text":"{F1} takes it from you, turns away from the wind to shield it, and reads it out in the steady voice of someone who has decided not to be cold."}]$p$::jsonb) where series_id = 'dark-moon' and season_number = 1 and week = 3 and day = 6;
update public.chapters set script = jsonb_insert(script, '{steps,4}', $p${"t":"say","text":"Not before one of them has had you face down in the ford, though. You come up streaming and coughing, with river grit in your teeth, and the cold of it stays in your boots all afternoon.","cond":{"on":"fight","won":false}}$p$::jsonb) where series_id = 'dark-moon' and season_number = 1 and week = 4 and day = 2;
update public.chapters set script = jsonb_insert(script, '{steps,8}', $p${"t":"say","text":"While it lasted he had the better of you. Your forearm aches where the oar came down across it, and the fog has found its way into your wet sleeves.","cond":{"on":"fight","won":false}}$p$::jsonb) where series_id = 'dark-moon' and season_number = 1 and week = 4 and day = 5;
update public.chapters set script = jsonb_insert(script, '{steps,17}', $p${"t":"say","text":"There is a row of tooth-marks through your sleeve, and the skin beneath is bruised but not broken. The child under the cart watches you rub at it, and says nothing.","cond":{"on":"fight","won":false}}$p$::jsonb) where series_id = 'dark-moon' and season_number = 1 and week = 5 and day = 2;
update public.chapters set script = jsonb_insert(script, '{steps,9}', $p${"t":"say","text":"It had you against the rock more than once before the end. Your shoulder is stiff, and your ears are still ringing with the iron of it.","cond":{"on":"fight","won":false}}$p$::jsonb) where series_id = 'dark-moon' and season_number = 1 and week = 6 and day = 4;
update public.chapters set script = jsonb_insert(script, '{steps,9}', $p${"t":"say","text":"It is down, but so are you, on one knee in the dust, and the cold of its grip is still round your wrist like a cuff.","cond":{"on":"fight","won":false}}$p$::jsonb) where series_id = 'dark-moon' and season_number = 1 and week = 6 and day = 6;
update public.gathering_scripts set data = jsonb_set(data, '{steps,20,text}', $p$"The way on is back across the gallery. {RISK} is three steps ahead of you when the floor gives.\n\nThere is no warning. A timber that has waited fifty years goes all at once. {RISK} drops through it to the chest and stops there, jammed, arms flung wide over boards that are already splitting. Below {RISK}'s boots there is nothing but the sound of the river, a long way down in the dark.\n\nNobody can walk out there. The boards that are holding {RISK} will not hold a second pair of feet.\n\nA rope is no use. {RISK}'s two arms are all that is holding {RISK} up, and neither can let go to catch one.\n\nOne of you can go out flat, on your belly, with the rest standing on the stone at the gallery's edge and holding your ankles, and haul. An arm has one haul like that in it. Then the next of you.\n\nAnd {RISK}, jammed in the boards, can do more than hang there. Every elbow got onto sounder wood, every hand's breadth won from below, counts as much as a haul from above.\n\n**This is a United Effort. One job, and you take it in turns.**"$p$::jsonb) where series_id = 'dark-moon' and season_number = 1 and week = 1;
update public.gathering_scripts set data = jsonb_set(jsonb_set(data, '{steps,61,rows,0,answer}', $p$"*\"Malakor.\"* And when you ask him how he knows it: *\"My grandmother taught me that name.\"*"$p$::jsonb), '{steps,61,rows,1,answer}', $p$"*\"I know the name.\"* And when you ask him how: *\"My family's been in these hills longer than the roads have.\"*"$p$::jsonb) where series_id = 'dark-moon' and season_number = 1 and week = 2;
update public.gathering_scripts set data = jsonb_set(jsonb_set(jsonb_set(data, '{steps,54,rows,5,answer}', $p$"He looks at you for a long moment, and says nothing at all."$p$::jsonb), '{steps,54,rows,11,answer}', $p$"*\"Most went home.\"* When you name the charcoal woman's nephew, he is quiet for a long moment. *\"Him we lost.\"* And then, lower: *\"Not by our choosing.\"*"$p$::jsonb), '{steps,54,rows,15,answer}', $p$"He looks past you, at the dark the way you came, and says nothing."$p$::jsonb) where series_id = 'dark-moon' and season_number = 1 and week = 3;
update public.gathering_scripts set data = jsonb_set(jsonb_set(jsonb_set(data, '{steps,30,rows,4,answer}', $p$"*\"Most went home.\"* When you name the charcoal woman's nephew, he is quiet for a long moment. *\"Him we lost.\"* And then, lower: *\"Not by our choosing.\"*"$p$::jsonb), '{steps,54,rows,2,answer}', $p$"*\"Yes.\"* When you ask him why, he looks down at the water and says nothing more."$p$::jsonb), '{steps,63,rows,1,answer}', $p$"He opens his mouth, and closes it again, and says nothing."$p$::jsonb) where series_id = 'dark-moon' and season_number = 1 and week = 4;